//UPLO   = 'L'
//TRANSA = 'T'
//DIAG   = 'U'
// => Form  B := alpha*A**T*B.
// A is MxM
// B is MxN
#pragma scop
  {
     #define TI 64
     #define TJ 64
     #pragma omp parallel default(none) shared(A, B, alpha, _PB_M, _PB_N)
     {
        #pragma omp single
        for (int ii = 0; ii < _PB_M; ii += TI)
           for (int jj = 0; jj < _PB_N; jj += TJ) {
              int i_end = (ii + TI < _PB_M) ? (ii + TI) : _PB_M;
              int j_end = (jj + TJ < _PB_N) ? (jj + TJ) : _PB_N;
